    public static string ResultLabel(string r) => r switch
    {
        "พบประวัติ"    => "พบประวัติ (ไม่ผ่าน)",
        "ไม่พบประวัติ" => "ไม่พบประวัติ (ผ่าน)",
        "รอผล"         => "รอผล",
        _              => r
    };

    public static string ResultClass(string r) => r switch
    {
        "พบประวัติ"    => "closed",
        "ไม่พบประวัติ" => "danger",
        "รอผล"         => "pending",
        _              => "pending"
    };

    // ผ่าน = ไม่พบประวัติ, ไม่ผ่าน = พบประวัติ
    public static string PassLabel(string r) => r switch
    {
        "ไม่พบประวัติ" => "ผ่าน",
        "พบประวัติ"    => "ไม่ผ่าน",
        _              => "รอผล"
    };

    public static double HitRate(IEnumerable<PersonCheckRecord> records)
    {
        var list = records.ToList();
        var denominator = list.Count(r => r.Result != "รอผล");
        if (denominator == 0) return 0;
        var hits = list.Count(r => r.Result == "พบประวัติ");
        return hits / (double)denominator * 100;
    }

    // FR-022: mask นามสกุลบุคคล ตาม PDPA
    public static string MaskName(PersonCheckRecord r)
    {
        if (r.TargetType != "บุคคล") return r.TargetName;
        var parts = r.TargetName.Split(' ', 2, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length < 2) return r.TargetName;
        return $"{parts[0]} {parts[1][0]}***";
    }
